1	//! The pegainfer server binary: pure dispatch over the compiled-in
2	//! [`ModelLine`]s. Every model-specific flag, rule, and option type lives in
3	//! its model crate; this file only wires detection, CLI validation, and the
4	//! serve path selection together.
5	
6	use std::time::Instant;
7	
8	use anyhow::Context;
9	use clap::FromArgMatches;
10	use log::info;
11	use pegainfer_core::logging;
12	use pegainfer_frontend::engine::LaunchedEngine;
13	use pegainfer_frontend::model_line::DetectError;
14	use pegainfer_frontend::model_line::LaunchContext;
15	use pegainfer_frontend::model_line::ModelLine;
16	use pegainfer_frontend::model_line::ModelLineRegistry;
17	use pegainfer_frontend::model_line::SharedArgs;
18	use pegainfer_frontend::model_line::provided_args;
19	
20	#[cfg(not(target_env = "msvc"))]
21	#[global_allocator]
22	static GLOBAL: tikv_jemallocator::Jemalloc = tikv_jemallocator::Jemalloc;
23	
24	fn model_lines() -> Vec<&'static dyn ModelLine> {
25	    vec![
26	        #[cfg(feature = "deepseek-v2-lite")]
27	        &pegainfer_deepseek_v2_lite::model_line::MODEL_LINE,
28	        #[cfg(feature = "gemma4")]
29	        &pegainfer_gemma4::model_line::MODEL_LINE,
30	        #[cfg(feature = "glm52")]
31	        &pegainfer_glm52::model_line::MODEL_LINE,
32	        #[cfg(feature = "k3")]
33	        &pegainfer_k3::model_line::MODEL_LINE,
34	        #[cfg(feature = "kimi-k2")]
35	        &pegainfer_kimi_k2::model_line::MODEL_LINE,
36	        #[cfg(feature = "qwen3")]
37	        &pegainfer_qwen3::model_line::MODEL_LINE,
38	        #[cfg(feature = "qwen35")]
39	        &pegainfer_qwen35::model_line::MODEL_LINE,
40	        #[cfg(feature = "qwen4")]
41	        &pegainfer_qwen4::model_line::MODEL_LINE,
42	    ]
43	}
44	
45	/// One row of [`families`]: a line's feature, the identities its `probe` claims,
46	/// and whether that line is compiled into this binary.
47	struct Family {
48	    feature: &'static str,
49	    model_types: &'static [&'static str],
50	    text_model_types: &'static [&'static str],
51	    compiled: bool,
52	}
53	
54	/// Every line the server can be built with, and the identities its `probe`
55	/// claims.
56	///
57	/// This is **a second source of truth by necessity**: the hint exists for the
58	/// case where the line — and therefore its `probe` — is compiled out, so these
59	/// strings cannot be read from the line crate. The `qwen4` row is bound to that
60	/// crate's own `MODEL_TYPE`/`TEXT_MODEL_TYPE` by a test under the feature
61	/// (`qwen4_hint_identity_matches_the_line_crate`).
62	///
63	/// The hint is **identity-only**: it cannot run a compiled-out probe, so it also
64	/// fires for a variant that probe would refuse — a quantized sibling (its
65	/// `quantization_config`), tied embeddings, a YaRN rope. It names the feature to
66	/// rebuild with; it is not a promise that the checkpoint is servable.
67	fn families() -> [Family; 8] {
68	    [
69	        Family {
70	            feature: "deepseek-v2-lite",
71	            model_types: &["deepseek_v2"],
72	            text_model_types: &[],
73	            compiled: cfg!(feature = "deepseek-v2-lite"),
74	        },
75	        Family {
76	            feature: "gemma4",
77	            model_types: &["gemma4", "gemma4_unified"],
78	            text_model_types: &["gemma4_text", "gemma4_unified_text"],
79	            compiled: cfg!(feature = "gemma4"),
80	        },
81	        Family {
82	            feature: "glm52",
83	            model_types: &["glm_moe_dsa"],
84	            text_model_types: &[],
85	            compiled: cfg!(feature = "glm52"),
86	        },
87	        Family {
88	            feature: "k3",
89	            model_types: &["kimi_k3"],
90	            text_model_types: &["kimi_linear"],
91	            compiled: cfg!(feature = "k3"),
92	        },
93	        Family {
94	            feature: "kimi-k2",
95	            model_types: &["kimi_k25", "kimi_k2"],
96	            text_model_types: &["kimi_k2"],
97	            compiled: cfg!(feature = "kimi-k2"),
98	        },
99	        Family {
100	            feature: "qwen3",
101	            model_types: &["qwen3"],
102	            text_model_types: &[],
103	            compiled: cfg!(feature = "qwen3"),
104	        },
105	        Family {
106	            feature: "qwen35",
107	            model_types: &["qwen3_5"],
108	            text_model_types: &["qwen3_5_text"],
109	            compiled: cfg!(feature = "qwen35"),
110	        },
111	        Family {
112	            feature: "qwen4",
113	            model_types: &["qwen4_exp"],
114	            text_model_types: &["qwen4_exp_text"],
115	            compiled: cfg!(feature = "qwen4"),
116	        },
117	    ]
118	}
119	
120	/// When no compiled-in line claims the config but the identity belongs to a
121	/// known family, tell the user which feature to rebuild with. See [`families`]
122	/// for the identity table and its limits.
123	fn feature_gate_hint(config: &serde_json::Value) -> Option<String> {
124	    let model_type = config
125	        .get("model_type")
126	        .and_then(serde_json::Value::as_str)
127	        .unwrap_or("");
128	    let text_model_type = config
129	        .get("text_config")
130	        .and_then(|text| text.get("model_type"))
131	        .and_then(serde_json::Value::as_str)
132	        .unwrap_or("");
133	    families().iter().find_map(|family| {
134	        (!family.compiled
135	            && (family.model_types.contains(&model_type)
136	                || family.text_model_types.contains(&text_model_type)))
137	        .then(|| {
138	            format!(
139	                "this looks like a {} model; rebuild pegainfer-server with --features {}",
140	                family.feature, family.feature
141	            )
142	        })
143	    })
144	}
145	
146	#[tokio::main]
147	async fn main() -> anyhow::Result<()> {
148	    logging::init_default();
149	    pegainfer_core::tracing::init();
150	
151	    let registry = ModelLineRegistry::new(model_lines());
152	    let cmd = registry.build_command(
153	        clap::Command::new("pegainfer")
154	            .version(env!("CARGO_PKG_VERSION"))
155	            .about("PegaInfer GPU inference server"),
156	    );
157	    let matches = cmd.clone().get_matches();
158	    let shared = SharedArgs::from_arg_matches(&matches)
159	        .map_err(|error| anyhow::anyhow!("invalid CLI args: {error}"))?;
160	    let provided = provided_args(&matches, &cmd);
161	
162	    let config_path = shared.model_path.join("config.json");
163	    let content = std::fs::read_to_string(&config_path)
164	        .with_context(|| format!("failed to read {}", config_path.display()))?;
165	    let config: serde_json::Value = serde_json::from_str(&content)
166	        .with_context(|| format!("failed to parse {}", config_path.display()))?;
167	
168	    let line = registry.detect(&config).map_err(|error| {
169	        if matches!(error, DetectError::NoMatch { .. }) {
170	            if let Some(hint) = feature_gate_hint(&config) {
171	                return anyhow::anyhow!("{error}; {hint}");
172	            }
173	        }
174	        anyhow::Error::from(error)
175	    })?;
176	
177	    registry.validate_provided(line, &provided, &cmd)?;
178	    shared.validate(&provided)?;
179	    let ctx = LaunchContext {
180	        model_path: &shared.model_path,
181	        config: &config,
182	        shared: &shared,
183	        matches: &matches,
184	    };
185	    line.validate(&ctx, &provided)?;
186	    let plan = line.serve_plan(&ctx)?;
187	
188	    info!("=== pegainfer - {} (GPU) ===", line.name());
189	    info!("Loading engine...");
190	    let start = Instant::now();
191	    info!(
192	        "Runtime: model_path={}, user-set flags {provided:?}",
193	        shared.model_path.display(),
194	    );
195	
196	    let model_path = shared.model_path.clone();
197	    let served_model_name = shared.served_model_name.clone();
198	    let tool_call_parser = plan.resolve_tool_call_parser(shared.tool_call_parser.clone());
199	    let port = shared.port;
200	
201	    // Engine load (weights → GPU) runs on a blocking thread so the HTTP
202	    // frontend (tokenizer, chat templates) loads concurrently. The frontend
203	    // binds only after the engine registers, so readiness is unchanged.
204	    let engine_load = tokio::task::spawn_blocking(move || -> anyhow::Result<LaunchedEngine> {
205	        let ctx = LaunchContext {
206	            model_path: &shared.model_path,
207	            config: &config,
208	            shared: &shared,
209	            matches: &matches,
210	        };
211	        line.launch(&ctx)
212	            .with_context(|| format!("failed to start {} engine", line.name()))
213	    });
214	
215	    let serve_result = if let Some(lora_modules) = plan.lora_modules {
216	        // LoRA routes need the engine's control plane when the router is
217	        // built, so this path stays sequential.
218	        let launched = engine_load
219	            .await
220	            .context("engine loader thread panicked")??;
221	        let LaunchedEngine::Stepped(engine) = launched else {
222	            anyhow::bail!("LoRA serving requires a step-driven engine");
223	        };
224	        info!("Engine loaded: elapsed_ms={}", start.elapsed().as_millis());
225	        let max_model_len =
226	            pegainfer_frontend::vllm::load_max_model_len(&model_path).unwrap_or(4096);
227	        pegainfer_frontend::vllm::serve_model_with_lora_routes(
228	            engine,
229	            model_path.to_string_lossy().into_owned(),
230	            served_model_name.into_iter().collect(),
231	            tool_call_parser,
232	            lora_modules,
233	            port,
234	            max_model_len,
235	            pegainfer_frontend::vllm::shutdown_token_from_ctrl_c(),
236	        )
237	        .await
238	    } else {
239	        let shutdown = tokio_util::sync::CancellationToken::new();
240	        let engine = {
241	            let shutdown = shutdown.clone();
242	            async move {
243	                let handle = engine_load
244	                    .await
245	                    .context("engine loader thread panicked")??;
246	                info!("Engine loaded: elapsed_ms={}", start.elapsed().as_millis());
247	                // The blocking load can't be cancelled, so SIGINT keeps its
248	                // default kill behavior until the engine is up; only then
249	                // switch to graceful shutdown.
250	                pegainfer_frontend::vllm::cancel_token_on_ctrl_c(&shutdown);
251	                anyhow::Ok(handle)
252	            }
253	        };
254	        if plan.prefill_only {
255	            pegainfer_frontend::vllm::serve_prefill_only_with_engine_count(
256	                engine,
257	                &model_path,
258	                served_model_name.into_iter().collect(),
259	                tool_call_parser.clone(),
260	                port,
261	                None,
262	                plan.scheduler_partition_count,
263	                shutdown,
264	            )
265	            .await
266	        } else {
267	            pegainfer_frontend::vllm::serve_with_engine_count(
268	                engine,
269	                &model_path,
270	                served_model_name.into_iter().collect(),
271	                tool_call_parser,
272	                port,
273	                None,
274	                plan.scheduler_partition_count,
275	                shutdown,
276	            )
277	            .await
278	        }
279	    }
280	    .context("vLLM frontend server failed");
281	
282	    // Export the final batch of request spans before the runtime tears down.
283	    // Flush before propagating an error too — a failed server is exactly where
284	    // the last buffered spans matter. No-op when tracing was never enabled.
285	    pegainfer_core::tracing::flush();
286	    serve_result?;
287	
288	    Ok(())
289	}
290	
291	#[cfg(test)]
292	mod tests {
293	    use super::*;
294	
295	    #[cfg(not(feature = "glm52"))]
296	    #[test]
297	    fn hint_names_the_feature_for_a_known_but_uncompiled_family() {
298	        let config = serde_json::json!({"model_type": "glm_moe_dsa"});
299	        let hint = feature_gate_hint(&config).expect("glm52 identity should hint");
300	        assert!(hint.contains("--features glm52"), "{hint}");
301	    }
302	
303	    #[cfg(not(feature = "gemma4"))]
304	    #[test]
305	    fn hint_matches_text_config_identities() {
306	        let config = serde_json::json!({"text_config": {"model_type": "gemma4_unified_text"}});
307	        let hint = feature_gate_hint(&config).expect("gemma4 text identity should hint");
308	        assert!(hint.contains("--features gemma4"), "{hint}");
309	    }
310	
311	    #[cfg(feature = "qwen3")]
312	    #[test]
313	    fn hint_is_silent_for_a_compiled_family() {
314	        let config = serde_json::json!({"model_type": "qwen3"});
315	        assert!(feature_gate_hint(&config).is_none());
316	    }
317	
318	    #[test]
319	    fn hint_is_silent_for_an_unknown_family() {
320	        let config = serde_json::json!({"model_type": "frobnicate_lm"});
321	        assert!(feature_gate_hint(&config).is_none());
322	    }
323	
324	    /// Binds the qwen4 row of [`families`] to the line crate's own constants, so
325	    /// changing one side without the other fails here.
326	    #[cfg(feature = "qwen4")]
327	    #[test]
328	    fn qwen4_hint_identity_matches_the_line_crate() {
329	        use pegainfer_qwen4::MODEL_TYPE;
330	        use pegainfer_qwen4::TEXT_MODEL_TYPE;
331	        let family = families()
332	            .into_iter()
333	            .find(|family| family.feature == "qwen4")
334	            .expect("the qwen4 family is always listed");
335	        assert_eq!(family.model_types, [MODEL_TYPE].as_slice());
336	        assert_eq!(family.text_model_types, [TEXT_MODEL_TYPE].as_slice());
337	    }
338	}
