1	//! The detection gate as the shipped binary runs it.
2	//!
3	//! The line's `probe` and the server's `feature_gate_hint` have unit tests, but
4	//! the wiring between them — `main` reading `config.json`, the registry's
5	//! `detect`, the hint, and `launch`'s refusal — is only exercised by running the
6	//! binary. This drives it against a model directory holding the frozen `qwen4_exp`
7	//! config and asserts the two shipped outcomes: a stock build names the feature to
8	//! rebuild with, an enabled build detects the line and then refuses to serve it.
9	//!
10	//! Neither path reaches CUDA: detection is pure, and `launch` bails before the
11	//! engine is built.
12	
13	use std::fs::File;
14	use std::path::Path;
15	use std::path::PathBuf;
16	use std::process::Command;
17	use std::process::ExitStatus;
18	use std::process::Stdio;
19	use std::time::Duration;
20	use std::time::Instant;
21	
22	/// The real checkpoint config, committed by the line crate. The server has no
23	/// fixture of its own, and the gate is meant to see the real thing.
24	const FROZEN_CONFIG: &str = include_str!(concat!(
25	    env!("CARGO_MANIFEST_DIR"),
26	    "/../pegainfer-qwen4/tests/frozen_config.json"
27	));
28	
29	/// The repo's own minimal tokenizer (`pegainfer-frontend/examples/echo-model`,
30	/// the fixture `examples/echo-server.rs` serves). An enabled build reaches the
31	/// serve path before `launch` bails, and the frontend refuses to start without a
32	/// tokenizer — which would surface *that* error instead of the refusal. The
33	/// engine failure then cancels the server so the refusal is what reaches stderr.
34	const TOKENIZER: &str = include_str!(concat!(
35	    env!("CARGO_MANIFEST_DIR"),
36	    "/../pegainfer-frontend/examples/echo-model/tokenizer.json"
37	));
38	
39	fn model_dir(tag: &str) -> PathBuf {
40	    let dir = std::env::temp_dir().join(format!(
41	        "pegainfer-detect-gate-{tag}-{}",
42	        std::process::id()
43	    ));
44	    std::fs::create_dir_all(&dir).unwrap();
45	    std::fs::write(dir.join("config.json"), FROZEN_CONFIG).unwrap();
46	    std::fs::write(dir.join("tokenizer.json"), TOKENIZER).unwrap();
47	    dir
48	}
49	
50	/// Both runs exit within a second once the binary is warm; this only has to
51	/// catch a startup or cancellation path that never returns.
52	const RUN_TIMEOUT: Duration = Duration::from_secs(60);
53	
54	/// Runs the binary against `model_path` and returns its exit status and stderr.
55	/// Stderr goes to a file, so a full pipe cannot stall the child, and a run past
56	/// `RUN_TIMEOUT` is killed and fails with what it printed so far.
57	fn run_against(model_path: &Path) -> (ExitStatus, String) {
58	    let log = model_path.join("stderr.log");
59	    let mut child = Command::new(env!("CARGO_BIN_EXE_pegainfer"))
60	        .arg("--model-path")
61	        .arg(model_path)
62	        .stdout(Stdio::null())
63	        .stderr(File::create(&log).expect("create the stderr log"))
64	        .spawn()
65	        .expect("spawn the pegainfer binary");
66	    let deadline = Instant::now() + RUN_TIMEOUT;
67	    let status = loop {
68	        if let Some(status) = child.try_wait().expect("poll the pegainfer binary") {
69	            break status;
70	        }
71	        if Instant::now() >= deadline {
72	            let _ = child.kill();
73	            let _ = child.wait();
74	            panic!(
75	                "the binary did not exit within {RUN_TIMEOUT:?}:\n{}",
76	                std::fs::read_to_string(&log).unwrap_or_default()
77	            );
78	        }
79	        std::thread::sleep(Duration::from_millis(50));
80	    };
81	    let stderr = std::fs::read_to_string(&log).expect("read the stderr log");
82	    (status, stderr)
83	}
84	
85	#[cfg(not(feature = "qwen4"))]
86	#[test]
87	fn stock_build_names_the_qwen4_feature() {
88	    let dir = model_dir("stock");
89	    let (status, stderr) = run_against(&dir);
90	    let _ = std::fs::remove_dir_all(&dir);
91	    assert!(
92	        !status.success(),
93	        "the stock build must not claim a qwen4_exp config"
94	    );
95	    assert!(
96	        stderr.contains("--features qwen4"),
97	        "the hint did not name the feature:\n{stderr}"
98	    );
99	}
100	
101	#[cfg(feature = "qwen4")]
102	#[test]
103	fn enabled_build_detects_the_line_and_refuses_to_serve() {
104	    let dir = model_dir("enabled");
105	    let (status, stderr) = run_against(&dir);
106	    let _ = std::fs::remove_dir_all(&dir);
107	    assert!(
108	        !status.success(),
109	        "the line must refuse to serve until inference is implemented"
110	    );
111	    assert!(
112	        stderr.contains("Qwen4"),
113	        "stderr did not name the detected line:\n{stderr}"
114	    );
115	    assert!(
116	        stderr.contains("not implemented"),
117	        "stderr did not carry the refusal reason:\n{stderr}"
118	    );
119	}
